// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/git/ChangesPanel.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * A session tile's code panel on its Changes view, ported from the app's
 * TileCodePanel (src/grid/TileCodePanel.tsx: its bar, the side pane and the
 * diff tab), CodeChanges (src/grid/CodeChanges.tsx: CodeViewSwitch,
 * CodeChangesList and CodeDiffView with its review), CodeLayoutButtons,
 * the code pickers' buttons (src/code/CodePickers.tsx) and the split handles
 * (src/ui/SplitHandle.tsx, src/grid/CodeSplitHandle.tsx).
 *
 * The app reads the changes from git and renders the diff with CodeMirror's
 * unified merge view; a scene passes a fixed diff and renders the markup
 * CodeMirror produces for it (cm-editor, gutters, cm-changedLine lines,
 * cm-deletedChunk widgets, cm-collapsedLines folds), with CodeMirror's
 * runtime styles in codeMirror.css.
 */
import { Fragment, useId, useState, type ReactNode } from "react";
import {
  Columns2,
  FileSearch,
  FolderTree,
  GitCompareArrows,
  ListTree,
  Maximize2,
  PanelLeft,
  Pencil,
  Rows2,
  Send,
  TextSearch,
  Trash2,
  X,
  type LucideIcon,
} from "lucide-react";
import "./codeMirror.css";

/* ------------------------------------------------------------ the data -- */

type ChangeStatus = "modified" | "added" | "untracked" | "deleted" | "renamed" | "conflicted";

/** STATUS_MARK (src/grid/CodeChanges.tsx). */
const STATUS_MARK: Record<ChangeStatus, { letter: string; label: string }> = {
  modified: { letter: "M", label: "Modified" },
  added: { letter: "A", label: "Added" },
  untracked: { letter: "U", label: "Untracked" },
  deleted: { letter: "D", label: "Deleted" },
  renamed: { letter: "R", label: "Renamed" },
  conflicted: { letter: "!", label: "Conflicted" },
};

interface ChangedFile {
  path: string;
  status: ChangeStatus;
}

/** The web project's working tree while its agent adds search to the notes
    page, in `git status --porcelain` order: tracked changes by path, then
    untracked files. */
const ROOT = "~/fieldnotes/web";
const FILES: ChangedFile[] = [
  { path: "components/NoteList.tsx", status: "modified" },
  { path: "lib/api.ts", status: "modified" },
  { path: "components/SearchBox.tsx", status: "untracked" },
  { path: "lib/search.ts", status: "untracked" },
];
const SHOWN = FILES[0];

/** ReviewLines and ReviewComment (src/grid/diffReview.ts). */
export interface ReviewLines {
  side: "old" | "new";
  from: number;
  to: number;
  removed: boolean;
}
export interface ReviewComment {
  path: string;
  lines: ReviewLines;
  note: string;
}

/** reviewLinesLabel (src/grid/diffReview.ts). */
function reviewLinesLabel(lines: ReviewLines): string {
  const span = lines.from === lines.to ? `line ${lines.from}` : `lines ${lines.from}-${lines.to}`;
  if (lines.side === "new") return span;
  return lines.removed ? `removed ${span}` : `${span} of the previous version`;
}

/* The diff of components/NoteList.tsx, as the unified merge view lays it
   out with the app's settings (lineDiff, collapseUnchanged margin 3 and
   minSize 4): one fold, five chunks, 8 added and 2 removed lines. Lines are
   written in a small markup: «k:text» is a highlighted token (k keyword or
   type, c comment or bracket, v variable, operator or attribute, p property,
   s string, g tag; the classes githubDark's rules generate) and ‹…› the
   characters the diff marks as changed (cm-changedText). */
const AFTER: string[] = [
  `«s:"use client"»;`,
  ``,
  `«k:import» «k:type» «c:{» «v:Page» «c:}» «k:from» «s:"@/lib/api"»;`,
  `‹«k:import» «c:{» «v:useSearch» «c:}» «k:from» «s:"@/lib/search"»;›`,
  `«k:import» «c:{» «v:NoteRow» «c:}» «k:from» «s:"./NoteRow"»;`,
  `‹«k:import» «c:{» «v:SearchBox» «c:}» «k:from» «s:"./SearchBox"»;›`,
  `«k:import» «c:{» «v:usePages» «c:}» «k:from» «s:"./usePages"»;`,
  ``,
  `«k:interface» «k:Props» «c:{»`,
  `  «p:first»: «k:Page»;`,
  `«c:}»`,
  ``,
  `«c:// Newest first. Older pages load as the»`,
  `«c:// sentinel at the bottom scrolls in.»`,
  `«k:export» «k:function» «v:NoteList»«c:(»«v:props»: «k:Props»«c:)» «c:{»`,
  `  «k:const» «c:{» «v:notes», «v:next», «v:sentinel» «c:}» «v:=»`,
  `    «v:usePages»«c:(»«v:props»«v:.»«p:first»«c:)»;`,
  `‹  «k:const» «c:{» «v:query», «v:setQuery», «v:results» «c:}» «v:=»›`,
  `‹    «v:useSearch»«c:()»;›`,
  ``,
  `  «k:return» «c:(»`,
  `    «c:<»«g:section» «v:className»=«s:"notes"»«c:>»`,
  `‹      «c:<»«g:SearchBox» «v:value»=«c:{»«v:query»«c:}»›`,
  `‹        «v:onChange»=«c:{»«v:setQuery»«c:}» «c:/>»›`,
  `      «c:<»«g:ul»«c:>»`,
  `        «c:{»‹«c:(»«v:results» «v:??» ›«v:notes»‹«c:)»›«v:.»«p:map»«c:((»«v:n»«c:)» => «c:(»`,
  `          «c:<»«g:NoteRow» «v:key»=«c:{»«v:n»«v:.»«p:id»«c:}» «v:note»=«c:{»«v:n»«c:}» «c:/>»`,
  `        «c:))}»`,
  `      «c:</»«g:ul»«c:>»`,
  `      «c:{»«v:next» «v:&&» ‹«v:!»«v:query» «v:&&» ›«c:(»`,
  `        «c:<»«g:div» «v:ref»=«c:{»«v:sentinel»«c:}» «c:/>»`,
  `      «c:)}»`,
  `    «c:</»«g:section»«c:>»`,
  `  «c:)»;`,
  `«c:}»`,
  ``,
];

/** The lines each chunk replaced, shown above it (the previous version). */
const REMOVED: Record<number, string[]> = {
  26: [`        «c:{»«v:notes»«v:.»«p:map»«c:((»«v:n»«c:)» => «c:(»`],
  30: [`      «c:{»«v:next» «v:&&» «c:(»`],
};
/** Lines of the current file inside a changed chunk (cm-changedLine). */
const CHANGED = new Set([4, 6, 18, 19, 23, 24, 26, 30]);
/** The unchanged stretch collapseUnchanged folds: lines 10-14. */
const FOLD = { from: 10, to: 14 };
const STATS = { added: 8, removed: 2 };

type Row =
  | { kind: "line"; n: number }
  | { kind: "deleted"; lines: string[] }
  | { kind: "collapsed"; lines: number };

const ROWS: Row[] = (() => {
  const rows: Row[] = [];
  for (let n = 1; n <= AFTER.length; n += 1) {
    if (n === FOLD.from) rows.push({ kind: "collapsed", lines: FOLD.to - FOLD.from + 1 });
    if (n >= FOLD.from && n <= FOLD.to) continue;
    const removed = REMOVED[n];
    if (removed) rows.push({ kind: "deleted", lines: removed });
    rows.push({ kind: "line", n });
  }
  return rows;
})();

/* Row heights as CodeMirror measures them, which it writes on the gutter
   elements: 12.5px code at line-height 1.4, and a fold of 10.5px text at the
   same line height with 3px padding above and below. */
const LINE_HEIGHT = 17.5;
const FOLD_HEIGHT = 20.7;
const CONTENT_PADDING = 4;
const rowHeight = (row: Row) =>
  row.kind === "line" ? LINE_HEIGHT : row.kind === "deleted" ? row.lines.length * LINE_HEIGHT : FOLD_HEIGHT;

/* ------------------------------------------------------- the code markup -- */

const TOKEN_CLASS: Record<string, string> = {
  k: "tok-keyword",
  c: "tok-comment",
  v: "tok-variable",
  p: "tok-property",
  s: "tok-string",
  g: "tok-tag",
};

interface Piece {
  text: string;
  className?: string;
  changed: boolean;
}

/** Splits a line of the markup above into its highlighted, changed pieces. */
function pieces(line: string): Piece[] {
  const out: Piece[] = [];
  let changed = false;
  let plain = "";
  const flush = () => {
    if (plain) out.push({ text: plain, changed });
    plain = "";
  };
  for (let at = 0; at < line.length; at += 1) {
    const char = line[at];
    if (char === "‹" || char === "›") {
      flush();
      changed = char === "‹";
    } else if (char === "«") {
      flush();
      const end = line.indexOf("»", at);
      out.push({ text: line.slice(at + 3, end), className: TOKEN_CLASS[line[at + 1]], changed });
      at = end;
    } else {
      plain += char;
    }
  }
  flush();
  return out;
}

const highlighted = (piece: Piece, key: number) =>
  piece.className ? <span key={key} className={piece.className}>{piece.text}</span> : <Fragment key={key}>{piece.text}</Fragment>;

/**
 * A line's text. In the editor the merge view's marks have the lower
 * precedence, so a changed run is one cm-changedText element around the
 * highlight spans it covers. A deleted chunk builds its own DOM, one span per
 * piece with the highlight class and cm-deletedText together.
 */
function CodeText({ line, deleted }: { line: string; deleted?: boolean }) {
  const all = pieces(line);
  if (deleted) {
    return (
      <>
        {all.map((piece, index) => {
          const className = [piece.className, piece.changed ? "cm-deletedText" : ""].filter(Boolean).join(" ");
          return className ? <span key={index} className={className}>{piece.text}</span> : <Fragment key={index}>{piece.text}</Fragment>;
        })}
      </>
    );
  }
  const runs: { changed: boolean; pieces: Piece[] }[] = [];
  for (const piece of all) {
    const last = runs[runs.length - 1];
    if (last && last.changed === piece.changed) last.pieces.push(piece);
    else runs.push({ changed: piece.changed, pieces: [piece] });
  }
  return (
    <>
      {runs.map((run, index) =>
        run.changed ? (
          <span key={index} className="cm-changedText">{run.pieces.map(highlighted)}</span>
        ) : (
          <Fragment key={index}>{run.pieces.map(highlighted)}</Fragment>
        ),
      )}
    </>
  );
}

/** The merge view's content rows: lines, deleted chunks and folds. */
function ContentRow({ row, commented }: { row: Row; commented: Set<number> }) {
  if (row.kind === "collapsed") {
    return <div className="cm-collapsedLines" contentEditable={false}>{`${row.lines} unchanged lines`}</div>;
  }
  if (row.kind === "deleted") {
    return (
      <div className="cm-deletedChunk" contentEditable={false}>
        {row.lines.map((line, index) => (
          <div key={index} className="cm-deletedLine">
            <del>
              <CodeText line={line} deleted />
            </del>
          </div>
        ))}
      </div>
    );
  }
  const changed = CHANGED.has(row.n);
  const className = ["cm-line", changed ? "cm-changedLine" : "", commented.has(row.n) ? "code-diff-commented" : ""].filter(Boolean).join(" ");
  const text = AFTER[row.n - 1];
  return (
    <div className={className}>
      {!text ? <br /> : changed ? <ins className="cm-insertedLine"><CodeText line={text} /></ins> : <CodeText line={text} />}
    </div>
  );
}

/**
 * The gutters: line numbers and the change gutter. A gutter element carries
 * its row's measured height; a widget with no marker (a fold, or a deleted
 * chunk in the line numbers) leaves a gap, which CodeMirror writes as the
 * next element's top margin.
 */
function Gutters() {
  const numbers: ReactNode[] = [
    <div key="spacer" className="cm-gutterElement" style={{ height: 0, visibility: "hidden", pointerEvents: "none" }}>99</div>,
  ];
  const changes: ReactNode[] = [];
  let numberGap = CONTENT_PADDING;
  let changeGap = CONTENT_PADDING;
  for (const [index, row] of ROWS.entries()) {
    const height = rowHeight(row);
    if (row.kind === "line") {
      numbers.push(
        <div key={index} className="cm-gutterElement" style={{ height, marginTop: numberGap || undefined }}>{row.n}</div>,
      );
      numberGap = 0;
    } else {
      numberGap += height;
    }
    if (row.kind === "collapsed") {
      changeGap += height;
      continue;
    }
    const marker = row.kind === "deleted" ? "cm-deletedLineGutter" : CHANGED.has(row.n) ? "cm-changedLineGutter" : "";
    changes.push(
      <div key={index} className={`cm-gutterElement${marker ? ` ${marker}` : ""}`} style={{ height, marginTop: changeGap || undefined }} />,
    );
    changeGap = 0;
  }
  const minHeight = ROWS.reduce((sum, row) => sum + rowHeight(row), CONTENT_PADDING * 2);
  return (
    <div className="cm-gutters cm-gutters-before" aria-hidden="true" style={{ minHeight, position: "sticky" }}>
      <div className="cm-gutter cm-lineNumbers">{numbers}</div>
      <div className="cm-gutter cm-changeGutter">{changes}</div>
    </div>
  );
}

/** The unified diff as @uiw/react-codemirror mounts it (CodeMirror with unifiedMergeView). */
function UnifiedDiff({ commented }: { commented: Set<number> }) {
  return (
    <div className="cm-theme code-diff-editor" style={{ height: "100%" }}>
      <div className="cm-editor cm-merge-b">
        <div className="cm-announced" aria-live="polite" />
        <div tabIndex={-1} className="cm-scroller">
          <Gutters />
          <div
            spellCheck={false}
            autoCorrect="off"
            autoCapitalize="off"
            translate="no"
            contentEditable={false}
            suppressContentEditableWarning
            className="cm-content"
            style={{ tabSize: 4 }}
            role="textbox"
            aria-multiline="true"
            aria-readonly="true"
          >
            {ROWS.map((row, index) => (
              <ContentRow key={index} row={row} commented={commented} />
            ))}
          </div>
          <div className="cm-layer cm-selectionLayer" aria-hidden="true" style={{ zIndex: -2 }} />
          <div className="cm-layer cm-cursorLayer" aria-hidden="true" />
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------- the diff -- */

/** One pending comment in the review list (ReviewCommentRow). */
function ReviewCommentRow({ comment }: { comment: ReviewComment }) {
  const where = `${comment.path} ${reviewLinesLabel(comment.lines)}`;
  return (
    <li className="code-diff-review-item">
      <span className="code-diff-review-where" title={where}>{where}</span>
      <input className="code-diff-ask-input" defaultValue={comment.note} aria-label={`Comment on ${where}`} spellCheck={false} maxLength={2000} />
      <button type="button" className="btn btn-sm code-diff-ask-btn code-diff-review-delete" aria-label={`Delete comment on ${where}`} title="Delete this comment">
        <Trash2 size={12} aria-hidden="true" />
      </button>
    </li>
  );
}

/**
 * CodeDiffView, Unified, with no lines selected: the legend, the pending
 * review (its count opens the list) and the layout switch over the diff.
 */
function DiffView({ comments }: { comments: ReviewComment[] }) {
  const [listOpen, setListOpen] = useState(comments.length > 0);
  const listId = "code-diff-review-web";
  const commented = new Set<number>();
  for (const comment of comments) {
    if (comment.path !== SHOWN.path || comment.lines.side !== "new") continue;
    for (let line = comment.lines.from; line <= comment.lines.to; line += 1) commented.add(line);
  }
  return (
    <div className="code-diff code-diff-unified">
      <div className="code-diff-bar">
        <span className="code-diff-legend" aria-hidden="true">
          <span className="code-diff-legend-del">− removed</span>
          <span className="code-diff-legend-add">+ added</span>
        </span>
        {comments.length ? (
          <span className="code-diff-review" role="group" aria-label="Pending review">
            <button
              type="button"
              className="code-diff-review-count"
              aria-expanded={listOpen}
              aria-controls={listId}
              title={listOpen ? "Hide the pending comments" : "Show the pending comments to edit or delete them"}
              onClick={() => setListOpen((open) => !open)}
            >
              {comments.length === 1 ? "1 comment" : `${comments.length} comments`}
            </button>
            <span className="code-diff-review-dot" aria-hidden="true">·</span>
            <button type="button" className="btn btn-sm code-diff-ask-btn" title="Type every pending comment to the agent in this tile as one review">
              <Send size={12} aria-hidden="true" />Send review
            </button>
          </span>
        ) : null}
        <span className="code-diff-mode" role="radiogroup" aria-label="Diff layout">
          {(["unified", "split"] as const).map((value) => (
            <button key={value} type="button" role="radio" aria-checked={value === "unified"} className={value === "unified" ? "on" : ""}>
              {value === "unified" ? <Rows2 size={12} aria-hidden="true" /> : <Columns2 size={12} aria-hidden="true" />}
              <span className="code-diff-mode-label">{value === "unified" ? "Unified" : "Split"}</span>
            </button>
          ))}
        </span>
      </div>
      {listOpen && comments.length ? (
        <ul className="code-diff-review-list" id={listId} aria-label="Pending review comments">
          {comments.map((comment) => (
            <ReviewCommentRow key={`${comment.path}:${comment.lines.from}`} comment={comment} />
          ))}
        </ul>
      ) : null}
      <UnifiedDiff commented={commented} />
    </div>
  );
}

/* ---------------------------------------------------------- side and bar -- */

function splitPath(path: string): { name: string; dir: string } {
  const at = path.lastIndexOf("/");
  return at < 0 ? { name: path, dir: "" } : { name: path.slice(at + 1), dir: path.slice(0, at) };
}

/** The Files / Changes switch and the changed files (CodeViewSwitch, CodeChangesList). */
function ChangesSide() {
  const panelId = useId();
  return (
    <div className="code-tile-tree code-changes-side">
      <div className="code-changes-switch" role="tablist" aria-label="Sidebar view">
        {(["files", "changes"] as const).map((value) => {
          const on = value === "changes";
          return (
            <button
              key={value}
              type="button"
              role="tab"
              id={`${panelId}-${value}`}
              aria-selected={on}
              aria-controls={panelId}
              tabIndex={on ? 0 : -1}
              className={`code-changes-tab${on ? " on" : ""}`}
              title={value === "files" ? "Files" : "Changes"}
            >
              {value === "files" ? <FolderTree size={13} aria-hidden="true" /> : <GitCompareArrows size={13} aria-hidden="true" />}
              <span className="code-changes-label">{value === "files" ? "Files" : "Changes"}</span>
              {value === "changes" ? <span className="code-changes-count">{FILES.length}</span> : null}
            </button>
          );
        })}
      </div>
      <div className="code-changes-pane" id={panelId} role="tabpanel" aria-labelledby={`${panelId}-changes`}>
        <div className="code-changes-list">
          {FILES.map((file) => {
            const mark = STATUS_MARK[file.status];
            const { name, dir } = splitPath(file.path);
            const on = file === SHOWN;
            return (
              <button
                key={`${file.status}:${file.path}`}
                type="button"
                className={`ft-row code-changes-row${on ? " on" : ""}`}
                title={`${mark.label}: ${file.path}`}
                aria-label={`${file.path}, ${mark.label.toLowerCase()}`}
                aria-current={on ? "true" : undefined}
              >
                <span className={`code-changes-status code-changes-status-${file.status}`} aria-hidden="true">{mark.letter}</span>
                <span className="ft-name">
                  <span className="code-changes-name">{name}</span>
                  {dir ? <span className="code-changes-dir">{dir}</span> : null}
                </span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

/** Quick Open, project search and the symbol outline (useCodePickers); the outline needs an open file. */
const PICKERS: { Icon: LucideIcon; label: string; shortcut: string; keys: string; needsFile?: boolean }[] = [
  { Icon: FileSearch, label: "Go to file", shortcut: "⌘P", keys: "Meta+P" },
  { Icon: TextSearch, label: "Search in folder", shortcut: "⇧⌘F", keys: "Meta+Shift+F" },
  { Icon: ListTree, label: "Go to symbol", shortcut: "⇧⌘O", keys: "Meta+Shift+O", needsFile: true },
];

/** The panel's bar on a diff: the tree toggle, the diff's tab, the pickers and the layout buttons. */
function CodeBar({ treeOpen }: { treeOpen: boolean }) {
  return (
    <div className="tile-code-bar">
      <button className={`tile-btn ${treeOpen ? "tile-btn-on" : ""}`} title={treeOpen ? "Hide tree" : "Show tree"}>
        <PanelLeft size={13} />
      </button>
      <div className="code-file-tab code-diff-tab" title={`${ROOT}/${SHOWN.path}`}>
        <span className="tile-code-name">{splitPath(SHOWN.path).name}</span>
        <span className="code-diff-stat" aria-label={`${STATS.added} added, ${STATS.removed} removed lines`}>
          <span className="code-diff-added">+{STATS.added}</span>
          <span className="code-diff-removed">−{STATS.removed}</span>
        </span>
        <button type="button" className="code-diff-edit" title={`Open ${SHOWN.path} in the editor`}>
          <Pencil size={12} aria-hidden="true" />
          <span className="code-diff-edit-label">Edit file</span>
        </button>
        <button type="button" className="tile-btn code-file-tab-close" title="Close diff" aria-label="Close diff">
          <X size={12} />
        </button>
      </div>
      <div className="tile-head-spacer" />
      {PICKERS.map(({ Icon, label, shortcut, keys, needsFile }) => (
        <button
          key={label}
          type="button"
          className="tile-btn code-picker-btn"
          title={`${label} (${shortcut})`}
          aria-label={label}
          aria-keyshortcuts={keys}
          disabled={needsFile}
        >
          <Icon size={13} aria-hidden="true" />
        </button>
      ))}
      <button type="button" className="tile-btn" title="Side by side: switch to stacked" aria-label="Side by side: switch to stacked">
        <Columns2 size={13} />
      </button>
      <button type="button" className="tile-btn" title="Full editor" aria-label="Full editor" aria-pressed={false}>
        <Maximize2 size={13} />
      </button>
      <button type="button" className="tile-btn" title="Close editor" aria-label="Close editor">
        <X size={13} />
      </button>
    </div>
  );
}

/* --------------------------------------------------------------- panel -- */

/**
 * The code panel beside the terminal on its Changes view, NoteList.tsx's
 * diff picked, plus the handle between the terminal and the panel. With
 * `comments`, a review is pending on the tile and its list is open.
 */
export function ChangesPanel({ treeOpen = true, comments = [] }: { treeOpen?: boolean; comments?: ReviewComment[] }) {
  return (
    <>
      <div className="tile-code">
        <CodeBar treeOpen={treeOpen} />
        <div className="code-split">
          {treeOpen ? <ChangesSide /> : null}
          {treeOpen ? (
            <div role="separator" tabIndex={0} aria-label="Resize file tree" aria-orientation="vertical" className="split-handle split-handle-x code-tree-handle" />
          ) : null}
          <div className="code-editor-pane">
            <DiffView comments={comments} />
          </div>
        </div>
      </div>
      <CodeSplitHandle />
    </>
  );
}

/** The terminal's share of the tile body (the split handle's value); the scenes set it on the tile. */
export const CODE_SPLIT = 0.38;

/* The fixed heights above the diff, from app.css: the panel's bar (27px
   buttons, 5px padding, a 1px rule), the diff's bar (the 26px layout switch,
   5px padding, a rule) and each open review comment (24px rows 4px apart,
   5px padding, a rule). */
const CODE_BAR = 38;
const DIFF_BAR = 37;
const reviewListHeight = (comments: number) => (comments ? 5 + comments * 24 + (comments - 1) * 4 + 5 + 1 : 0);

/**
 * The panel height whose diff ends exactly after its first `rows` rows, so a
 * scene can size the tile for the editor to stop between two lines.
 */
export function changesPanelHeight(rows: number, comments = 0): number {
  const diff = ROWS.slice(0, rows).reduce((sum, row) => sum + rowHeight(row), CONTENT_PADDING);
  return CODE_BAR + DIFF_BAR + reviewListHeight(comments) + diff;
}

function CodeSplitHandle() {
  return (
    <div
      role="separator"
      tabIndex={0}
      aria-label="Resize terminal and editor"
      aria-orientation="vertical"
      aria-valuenow={Math.round(CODE_SPLIT * 100)}
      aria-valuemin={15}
      aria-valuemax={85}
      className="split-handle split-handle-x code-split-handle"
    />
  );
}
